@namespace CheckoutWizard.Components

<div class="checkout-wizard">
    @if (_step == Step.Shipping)
    {
        <ShippingStep Shipping="@_order.Shipping"
                      OnNext="@HandleShippingComplete" />
    }
    else
    {
        <PaymentStep Payment="@_order.Payment"
                     OnBack="@GoBackToShipping"
                     OnPlaceOrder="@HandlePlaceOrder" />
    }
</div>

@code {
    private enum Step { Shipping, Payment }

    [Parameter]
    public EventCallback<Order> OnOrderPlaced { get; set; }

    private readonly Order _order = new();
    private Step _step = Step.Shipping;

    private void HandleShippingComplete()
    {
        _step = Step.Payment;
    }

    private void GoBackToShipping()
    {
        _step = Step.Shipping;
    }

    private async Task HandlePlaceOrder()
    {
        await OnOrderPlaced.InvokeAsync(_order);
    }
}

@namespace CheckoutWizard.Components
@implements IDisposable
@inject IAddressValidator AddressValidator

<fieldset disabled="@_isValidating">
    <legend>Shipping Information</legend>

    <div class="form-group">
        <label for="name">Name</label>
        <input id="name" @bind="Shipping.Name" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="address">Address</label>
        <input id="address" @bind="Shipping.Address" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="city">City</label>
        <input id="city" @bind="Shipping.City" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="zip">Zip Code</label>
        <input id="zip" @bind="Shipping.ZipCode" @bind:event="oninput" />
    </div>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-error" role="alert">@_validationError</div>
    }
</fieldset>

<button disabled="@_isValidating" @onclick="ValidateAndProceed">
    @if (_isValidating)
    {
        <span class="spinner" aria-hidden="true"></span>
        <span>Validating…</span>
    }
    else
    {
        <span>Next</span>
    }
</button>

@code {
    [Parameter]
    public ShippingInfo Shipping { get; set; } = default!;

    [Parameter]
    public EventCallback OnNext { get; set; }

    private CancellationTokenSource? _cts;
    private bool _isValidating;
    private string? _validationError;

    private async Task ValidateAndProceed()
    {
        _validationError = null;

        // Cancel any in-flight validation before starting a new one.
        CancelPendingValidation();

        var cts = new CancellationTokenSource();
        _cts = cts;
        _isValidating = true;

        try
        {
            var isValid = await AddressValidator.ValidateAddressAsync(
                Shipping.Address, Shipping.City, Shipping.ZipCode, cts.Token);

            // Guard against acting on a stale result after cancellation.
            if (cts.Token.IsCancellationRequested)
                return;

            if (isValid)
            {
                await OnNext.InvokeAsync();
            }
            else
            {
                _validationError = "The address could not be verified. Please check your details.";
            }
        }
        catch (OperationCanceledException)
        {
            // Expected when the user re-clicks Next or navigates away.
        }
        catch (Exception)
        {
            if (!cts.Token.IsCancellationRequested)
            {
                _validationError = "An error occurred while validating the address. Please try again.";
            }
        }
        finally
        {
            // Only flip the flag if this is still the active operation.
            if (_cts == cts)
            {
                _isValidating = false;
            }
        }
    }

    private void CancelPendingValidation()
    {
        if (_cts is not null)
        {
            _cts.Cancel();
            _cts.Dispose();
            _cts = null;
        }
    }

    public void Dispose()
    {
        CancelPendingValidation();
    }
}

